  $city=trim((string)($_GET['city']??''));if($city!==''){$s=$pdo->prepare("SELECT l.*,COALESCE(AVG(r.rating),0) avg_rating,COUNT(r.id) review_count FROM locations l LEFT JOIN reviews r ON r.location_id=l.id AND r.status='published' WHERE l.status='active' AND (l.city LIKE ? OR l.address LIKE ? OR l.name LIKE ?) GROUP BY l.id ORDER BY l.city,l.name");$like='%'.$city.'%';$s->execute([$like,$like,$like]);}else{$s=$pdo->query("SELECT l.*,COALESCE(AVG(r.rating),0) avg_rating,COUNT(r.id) review_count FROM locations l LEFT JOIN reviews r ON r.location_id=l.id AND r.status='published' WHERE l.status='active' GROUP BY l.id ORDER BY l.created_at DESC LIMIT 12");}$locations=$s->fetchAll();layout_start('Luggage storage, made simple');?>
